// Independent reproduction of observed string-column contains; no providers.
function baselineLookup(rows,query_column,query_value){return rows.filter(row=>String(row[query_column]).includes(query_value));}

const columns=['ID','Full Name','First Name','Last Name','Phone','Email','Events','Manager','Active'];
const fail=code=>{throw new Error(code)};
function volunteerLookup(rows,query,principal){
  if(!principal||typeof principal.userId!=='string'||!principal.userId||principal.read!==true)fail('READ_DENIED');
  if(!Array.isArray(rows))fail('INVALID_ROWS');
  const ids=new Set();
  for(const row of rows){
    if(!row||Object.prototype.toString.call(row)!=='[object Object]'||Object.getOwnPropertySymbols(row).length)fail('INVALID_ROWS');
    const descriptors=Object.getOwnPropertyDescriptors(row);
    if(Object.keys(descriptors).length!==columns.length||columns.some(column=>!Object.hasOwn(descriptors,column)||!Object.hasOwn(descriptors[column],'value')||descriptors[column].enumerable!==true||typeof descriptors[column].value!=='string'||!descriptors[column].value.trim())||!['Yes','No'].includes(row.Active)||ids.has(row.ID))fail('INVALID_ROWS');
    ids.add(row.ID);
  }
  if(!query||!columns.includes(query.query_column)||typeof query.query_value!=='string'||!query.query_value.trim()||query.query_value.length>200)fail('INVALID_QUERY');
  return baselineLookup(rows,query.query_column,query.query_value).map(row=>({...row}));
}

const input=$input.first().json;return volunteerLookup(input.rows,input.query,input.principal).map(row=>({json:{...row,scope:"Invented local records; read authority is a fixture, no external provider is called"}}));
